package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.BackchannelLogoutUriVO;

class BackchannelLogoutUriValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of backchannel logout uri of oauth client")
  void test_backchannel_logout_uri_value_holder_assign_plain_value() {
    Object holder = new Object();
    BackchannelLogoutUriValueHolder<Object> value = new BackchannelLogoutUriValueHolder<>(holder);
    Assertions.assertSame(holder, value.backchannelLogoutUri("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getBackchannelLogoutUriValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getBackchannelLogoutUri().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.backchannelLogoutUriNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getBackchannelLogoutUriValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getBackchannelLogoutUri().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of backchannel logout uri of oauth client")
  void test_backchannel_logout_uri_value_holder_assign_value_object() {
    Object holder = new Object();
    BackchannelLogoutUriValueHolder<Object> value = new BackchannelLogoutUriValueHolder<>(holder);
    BackchannelLogoutUriVO vo = BackchannelLogoutUriVO.from("one");
    Assertions.assertFalse(value.getBackchannelLogoutUriValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.backchannelLogoutUri(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getBackchannelLogoutUriValue().orElseThrow());
    Assertions.assertSame(holder, value.backchannelLogoutUri(Optional.empty()));
    Assertions.assertFalse(value.getBackchannelLogoutUriValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.backchannelLogoutUri(Optional.of(vo)));
    Assertions.assertSame(vo, value.getBackchannelLogoutUriValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of backchannel logout uri of oauth client against the original")
  void test_backchannel_logout_uri_value_holder_read() {
    Object holder = new Object();
    BackchannelLogoutUriValueHolder<Object> value = new BackchannelLogoutUriValueHolder<>(holder);
    BackchannelLogoutUriVO vo = BackchannelLogoutUriVO.from("one");
    BackchannelLogoutUriVO other = BackchannelLogoutUriVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getBackchannelLogoutUriValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readBackchannelLogoutUri(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readBackchannelLogoutUri(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.backchannelLogoutUri(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readBackchannelLogoutUri(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readBackchannelLogoutUri(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of backchannel logout uri of oauth client")
  void test_backchannel_logout_uri_value_holder_unset() {
    Object holder = new Object();
    BackchannelLogoutUriValueHolder<Object> value = new BackchannelLogoutUriValueHolder<>(holder);
    BackchannelLogoutUriVO vo = BackchannelLogoutUriVO.from("one");
    value.backchannelLogoutUri(vo);
    Assertions.assertSame(holder,
        value.unsetBackchannelLogoutUriIfMatches("backchannelLogoutUri_other"));
    Assertions.assertTrue(value.getBackchannelLogoutUriValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetBackchannelLogoutUriIfMatches("backchannelLogoutUri"));
    Assertions.assertFalse(value.getBackchannelLogoutUriValue().isPresent(),
        "The field name must clear the value");
    value.backchannelLogoutUri(vo);
    Assertions.assertSame(holder, value.unsetBackchannelLogoutUri());
    Assertions.assertFalse(value.getBackchannelLogoutUriValue().isPresent(),
        "Unset must clear the value");
  }
}
